// The mushroom kinds that were drawn as text rather than by hand.
//
// The first seven kinds on the sheet are the artist's. These six are written
// here as grids, and this file is their source: change a grid and rerun
// tools/make-mushroom-colours.mjs to change the mushroom. A shape edit is then
// a reviewable diff of characters rather than an opaque change to a PNG — the
// same arrangement as the generated flowers in tools/make-flower-kinds.mjs.
//
// Each grid is the *inside* only; the outline is generated by the rule in
// tools/outline.mjs, which reproduces the hand-drawn caps pixel for pixel. Keep
// every coloured pixel at least two in from the edge, or its outline falls off
// the sprite (there is a test).
//
// Legend
//   b c   the cap, base and shade — the two colours every colour swaps
//   d     a fixed white
//   e f   the stem, shadow and lit — the drawn kinds' stem colours, never swapped
//   .     nothing
//
// A kind is coloured exactly the way the drawn ones are: every colour is the
// same grid with a different b/c pair, and the rainbow lays the drawn rainbow's
// seven colours across the cap in diagonal bands. Which colours a kind comes in
// is the sim's business (COLOURS in js/sim/mushrooms.js); what those names look
// like is CAPS below, plus GENERATED_COLOURS for the six generated ones.

import { isOutline } from './outline.mjs';
import { GENERATED_COLOURS } from '../js/sim/mushrooms.js';

const T = 16;

export const FIXED = {
  o: [63, 38, 49],
  d: [255, 255, 255],
  e: [189, 108, 74], f: [234, 165, 108],
};

/**
 * Base and shade for every drawn colour name a generated kind uses, read off
 * the drawn sheet. Where a name means slightly different pairs on different
 * drawn kinds (Tan, Orange), the bolete's is used — the cleanest two-colour one.
 */
export const CAPS = {
  Lime: { base: [153, 229, 80], shade: [106, 190, 48] },
  Cyan: { base: [95, 205, 228], shade: [65, 140, 156] },
  Frost: { base: [203, 219, 252], shade: [255, 255, 255] },
  Tan: { base: [193, 151, 108], shade: [203, 163, 122] },
  Orange: { base: [223, 113, 38], shade: [255, 153, 83] },
  Blue: { base: [115, 134, 250], shade: [91, 110, 225] },
  Spotted: { base: [172, 50, 50], shade: [255, 255, 255] },
  Red: { base: [232, 69, 55], shade: [255, 112, 109] },
  Green: { base: [55, 148, 110], shade: [106, 190, 48] },
  Pink: { base: [215, 123, 186], shade: [234, 146, 206] },
  Navy: { base: [63, 63, 116], shade: [91, 91, 156] },
  Umber: { base: [82, 75, 36], shade: [130, 121, 67] },
  Violet: { base: [177, 94, 151], shade: [234, 149, 207] },
  Brown: { base: [143, 86, 59], shade: [224, 132, 70] },
  Ash: { base: [89, 86, 82], shade: [130, 128, 125] },
  ...Object.fromEntries(GENERATED_COLOURS.map((c) => [c.name, { base: c.base, shade: c.shade }])),
};

/** The drawn rainbow's seven colours, red to violet. */
export const RAINBOW = [
  [221, 0, 0], [254, 98, 48], [254, 246, 0], [0, 187, 0], [0, 155, 254], [0, 0, 131], [48, 0, 155],
];

const NONE = ['................', '................', '................'];

