    '...b...b...b....',
    '...b..bb..bb....',
    '...bb.b..bb.....',
    '....bbb..b...b..',
    '.....bbbbb..bb..',
    '..b...bbb..bb...',
    '..bb..bbbbbb....',
    '...bbbbbbb......',
