/**
 * One 16x16 sprite, outline included.
 *
 * @param {string[]} rows   a design
 * @param {{base: number[], shade: number[]} | 'rainbow'} cap
 */
export function build(rows, cap) {
  if (rows.length !== T || rows.some((r) => r.length !== T)) {
    throw new Error(`a design is ${T}x${T}: got ${rows.map((r) => r.length).join(',')}`);
  }
  const grid = rows.map((r) => [...r]);
  for (const row of grid) {
    for (const c of row) {
      if (c !== '.' && c !== 'b' && c !== 'c' && !FIXED[c]) throw new Error(`no colour for "${c}"`);
    }
  }
  const inside = (x, y) => y >= 0 && y < T && x >= 0 && x < T
    && grid[y][x] !== '.' && grid[y][x] !== 'o';

  // The rainbow runs corner to corner across the cap in diagonal bands, shared
  // out over the diagonals the cap actually covers — so a bunch of separate
  // little caps, with empty diagonals between them, still gets every colour.
  const diagonals = new Set();
  grid.forEach((row, y) => row.forEach((c, x) => { if (c === 'b' || c === 'c') diagonals.add(x + y); }));
  const order = [...diagonals].sort((a, b) => a - b);
  const band = (x, y) => RAINBOW[Math.floor(order.indexOf(x + y) * RAINBOW.length / order.length)];

  const rgba = Buffer.alloc(T * T * 4);
  for (let y = 0; y < T; y++) {
    for (let x = 0; x < T; x++) {
      const c = grid[y][x];
      let rgb;
      if (c === '.') {
        if (!isOutline(inside, x, y)) continue;
        rgb = FIXED.o;
      } else if (c === 'b' || c === 'c') {
        rgb = cap === 'rainbow' ? band(x, y) : (c === 'b' ? cap.base : cap.shade);
      } else {
        rgb = FIXED[c];
      }
      const i = (y * T + x) * 4;
      rgba[i] = rgb[0]; rgba[i + 1] = rgb[1]; rgba[i + 2] = rgb[2]; rgba[i + 3] = 255;
    }
  }
  return rgba;
}

/**
 * Every sprite of one kind, in sheet order: one per colour name, the last
 * always the rainbow.
 * @param {string} kind
 * @param {string[]} colours  the kind's colour names, as COLOURS lists them
 */
export function buildKind(kind, colours) {
  const rows = DESIGNS[kind];
  if (!rows) throw new Error(`${kind} has no design`);
  return colours.map((name) => {
    if (name === 'Rainbow') return build(rows, 'rainbow');
    if (!CAPS[name]) throw new Error(`${kind}: no cap colours for "${name}"`);
    return build(rows, CAPS[name]);
  });
}
